func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main_ok", main != null, "La scena principale deve caricarsi senza errori"):
		return
	await wait_seconds(0.5)
	check("no_errors", errors_text() == "", "L'esecuzione non deve provocare errori a schermo: " + errors_text())
	var active_raw = get_prop(main, "active_items", [])
	var active: Array = active_raw if active_raw is Array else []
	var over_limit := false
	for item in active:
		if is_instance_valid(item):
			var pos = get_prop(item, "position", Vector2.ZERO)
			if pos.y > 400.0:
				over_limit = true
				break
	check("items_cleared", not over_limit and active.size() == 0, "Tutti gli elementi oltre la soglia devono essere stati rimossi dall'array active_items")
